// This file is generated by AI.

// 后端报错的显示处理。
//
// GSOV 的报错是**给日志看的**: 颜色转义、几十个星号的横幅、多行堆栈, 一条错误动辄
// 二三十行。直接把它塞进历史卡片, 一个失败项就能占满整栏并把别的记录挤走。因此:
// 卡片里只留一行摘要, 全文留给弹窗按需查看。
//
// 这里只做显示处理, 不改动 `HistoryEntry.error` 里保存的原文。

/*
 * ANSI 颜色转义 (`ESC [ 93 m`)。
 * ESC 用码点拼出来: 正则字面量里直接写控制字符会被 lint 拒绝 (`no-control-regex`)。
 */
const ANSI_COLOR = new RegExp(`${String.fromCharCode(27)}\\[[0-9;]*[A-Za-z]`, 'g');

/** 去掉 ANSI 颜色转义 (含日志层剥掉 ESC 后残留的 `[93m` 形式) */
function stripAnsi(text: string): string {
  return text.replace(ANSI_COLOR, '').replace(/\[\d{1,2}(?:;\d{1,2})*m/g, '');
}

/** 只由横幅字符构成的整行 (日志里用来框住报错) */
const BANNER_LINE = /^[*=~_\-—]{6,}$/;

/** 清理日志噪声: 去颜色、去横幅星号、统一换行 */
function cleanLog(raw: string): string {
  return stripAnsi(raw)
    .replace(/\*{6,}/g, '')
    .split(/\r?\n/)
    .map((line) => line.replace(/\s+$/, ''))
    .filter((line) => !BANNER_LINE.test(line.trim()))
    .join('\n');
}

/** 完整报错文本 (弹窗里展示; 保留换行, 折叠连续空行) */
export function errorDetail(raw: string): string {
  const kept: string[] = [];
  for (const line of cleanLog(raw).split('\n')) {
    if (!line.trim() && !kept[kept.length - 1]?.trim()) continue;
    kept.push(line);
  }
  return kept.join('\n').trim();
}

/**
 * 一行摘要 (历史卡片里显示)。
 *
 * 取的是**整段压缩成一行**后的前缀, 不是"第一行": GSOV 的第一行往往只有
 * `GSOV 返回错误 (400):`, 真正有用的信息在第二行。
 */
export function errorSummary(raw: string, limit = 96): string {
  const single = errorDetail(raw).replace(/\s+/g, ' ').trim();
  if (!single) return '生成失败';
  return single.length > limit ? `${single.slice(0, limit - 1)}…` : single;
}

/**
 * 从报错里提炼"可执行的下一步"。
 *
 * 目前只认 NLTK 缺资源这一种 —— 整合包里最常见的环境问题, 而且报错自己就写着该跑
 * 哪条命令, 直接抄给用户比让他去读堆栈快得多。
 */
export function errorHint(raw: string): string | null {
  const match = /nltk\.download\(['"]([^'"]+)['"]\)/.exec(stripAnsi(raw));
  if (!match) return null;
  const resource = match[1];
  return `缺少 NLTK 资源 ${resource}：在整合包所用的 Python 环境里执行 python -m nltk.downloader ${resource}，然后重试。`;
}
